import{_ as t,a}from"./chunks/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges.DICf6X49.js";import{_ as s,o as u,c as o,a3 as n,j as e,a as r}from"./chunks/framework.z_KJ15Ep.js";const g="/bilder/unterricht-kataloge/ankreuzkompetenzen-uebersicht.png",d="/bilder/unterricht-kataloge/kataloge-ankreuzkompetenzen-anlegen.png",l="/bilder/unterricht-kataloge/kataloge-ankreuzkompetenzen-unterkategorien-beispiel.png",h="/bilder/unterricht-kataloge/kataloge-ankreuzkompetenzen-zeilenumbruch.png",p="/bilder/unterricht-kataloge/kataloge-ankreuzkompetenzen-zeilenumbruch-beispiel.png",m="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges-uebergangsempfehlung.png",c="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges-uebergangsempfehlung-unterkategorie.png",z="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges-uebergangsempfehlung-ausdruck.png",B=JSON.parse('{"title":"Ankreuzkompetenzen und Bewertungsstufen vorbereiten","description":"","frontmatter":{"title":"Ankreuzkompetenzen und Bewertungsstufen vorbereiten","source_pageid":1076,"source_revision":5883},"headers":[],"relativePath":"schild3/unterricht-kataloge/ankreuzkompetenzen-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/ankreuzkompetenzen-schulbezogene-kataloge.md"}'),k={name:"schild3/unterricht-kataloge/ankreuzkompetenzen-schulbezogene-kataloge.md"};function b(f,i,w,_,S,A){return u(),o("div",null,[...i[0]||(i[0]=[n('<h1 id="ankreuzkompetenzen-und-bewertungsstufen-vorbereiten" tabindex="-1">Ankreuzkompetenzen und Bewertungsstufen vorbereiten <a class="header-anchor" href="#ankreuzkompetenzen-und-bewertungsstufen-vorbereiten" aria-label="Permalink to &quot;Ankreuzkompetenzen und Bewertungsstufen vorbereiten&quot;">​</a></h1><p><a href="/bilder/unterricht-kataloge/ankreuzkompetenzen-uebersicht.png"><img src="'+g+'" alt="Ankreuzkompetenzen mit Filtern und Import-/Export-Schaltern" loading="lazy"></a></p><p><em>Ankreuzkompetenzen mit Filtern und Import-/Export-Schaltern — Oberfläche von SchILD-NRW 3.6.0.</em></p><p>Definieren Sie Kompetenzen nach Fach, Jahrgang und Halbjahr sowie die zugehörigen Bewertungsstufen. Die Angaben dienen als Grundlage für passende Ankreuzzeugnisse.</p><p>Die aktuelle Ansicht bietet Filter für <strong>Fach</strong>, <strong>Jahrgang</strong>, <strong>Halbjahr</strong> und <strong>Gliederung</strong> sowie <strong>Import</strong> und <strong>Export</strong>. Dafür stehen Excel-Import und Excel-Export zur Verfügung. Eine Ankreuzfloskel kann mehreren Jahrgängen zugeordnet werden. Die ausgefüllten Detailbilder zeigen Beispiele für Kompetenztexte, Unterkategorien und Zeugnisrubriken.</p><h2 id="ankreuzkompetenzen-anlegen" tabindex="-1">Ankreuzkompetenzen anlegen <a class="header-anchor" href="#ankreuzkompetenzen-anlegen" aria-label="Permalink to &quot;Ankreuzkompetenzen anlegen&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/kataloge-ankreuzkompetenzen-anlegen.png"><img src="'+d+'" alt="Legen Sie Ankreuzkompetenzen für die Jahrgänge und Fächer an." loading="lazy"></a></p><p><em>Legen Sie Ankreuzkompetenzen für die <strong>Jahrgänge</strong> und <strong>Fächer</strong> an.</em></p><p>SchILD-NRW unterstützt zusammen mit dem passenden Report die Verwendung von Ankreuzzeugnissen, bei denen definierte Kompetenzen in vier oder fünf Stufen bewertet werden.</p><p>Schauen Sie zur Verwendung in den Tutorial-Artikel zu <a href="/zeugnisse/grundschule/grundschulzeugnisse-ankreuzzeugnis-tutorial.html">Grundschul-Ankreuzzeugnissen</a>.</p><p>Die Ankreuzkompetenzen werden über <em>Kataloge</em> ➜ <strong>Angaben für Ankreuzzeugnisse</strong> eingestellt.</p><p>Hierbei werden für jeden <strong>Jahrgang</strong> und für jedes <strong>Fach</strong> die Kompetenzen vergeben. Weiterhin gibt es zwei Pseudo-Fächer, für die wie für die anderen Fächer Kompetenzen zugeordnet werden können.</p><p>Zum einen ist so das <em>&quot;Arbeits- und Sozialverhalten&quot; - ASV</em> bewertbar. Außerdem steht das Fach <em>Sonstiges</em> zur Verfügung, mit dem die <em>Frei definierbare Zeugnisrubrik</em> verwendet werden kann.</p><p>Neben dem <strong>Fach</strong> und dem <strong>Jahrgang</strong> ist das <strong>Halbjahr</strong> - oder beide - einzustellen, in dem die entsprechende Kompetenz bewertet werden soll.</p><p>In der <strong>Kompetenzbeschreibung</strong> ist die sprachliche Beschreibung der Kompetenz auszufüllen.</p><p>Über die Zahlen in <strong>Sortierung</strong> wird festgelegt, in welcher Reihenfolge die Kompetenzen auf dem Zeugnis erscheinen.</p>',16),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),r("Wichtig")]),e("p",null,"Die der Bewertung zugrunde liegenden Kompetenzen werden letztendlich über die entsprechenden Fach- und Schulkonferenzen festgelegt.")],-1),n('<h3 id="unterkategorien" tabindex="-1">Unterkategorien <a class="header-anchor" href="#unterkategorien" aria-label="Permalink to &quot;Unterkategorien&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-ankreuzkompetenzen-unterkategorien-beispiel.png"><img src="'+l+`" alt="In diesem Beispielzeugnis werden erst die Kompetenzen ohne Unterkategorien gezeigt, dann folgen die weiteren Kompetenzen, die Unterkategorien zugeordnet wurden." loading="lazy"></a></p><p><em>In diesem Beispielzeugnis werden erst die Kompetenzen ohne Unterkategorien gezeigt, dann folgen die weiteren Kompetenzen, die Unterkategorien zugeordnet wurden.</em></p><p>Es ist möglich, Unterkategorien festzulegen. Hierbei gilt, dass in Doppelpunkt <strong>:</strong> die Unterkategorie von der Kompetenz trennt. Für das <em>Arbeits- und Sozialverhalten</em> könnten die Kompetenzen zum Beispiel in die Unterkategorien <em>Lern- und Leistungsbereitschaft</em>, <em>Zuverlässigkeit und Sorgfalt</em> und <em>Soziales Miteinander</em> aufgeteilt werden.</p><p>Somit gilt dieses Schema:</p><pre><code> &quot;Unterkategorie&quot;: &quot;Kompetenz&quot;
</code></pre><p>Es können natürlich weiterhin Kompetenzen ohne Unterkategorie eingetragen werden.</p><p>Beispielsweise könnten diese Unterkategorien gesetzt werden:</p><pre><code> Lern- und Leistungsbereitschaft: ... beteiligt sich zielorientiert und sachbezogen.
 Lern- und Leistungsbereitschaft: ... bearbeitet die Aufgaben konzentriert im Rahmen der Zeitvorgaben.
 Lern- und Leistungsbereitschaft: ... beteiligt sich am Unterricht.
 Soziales Miteinander: ... übernimmt Aufgaben für die Gemeinschaft.
 Soziales Miteinander: ... hält sich an vereinbarte Schul- und Klassenregeln.
 Soziales Miteinander: ... begegnet anderen mit Respekt und Höflichkeit
 Soziales Miteinander: ... reagiert in Konfliktsituationen angemessen.
 Zuverlässigkeit und Sorgfalt: ... strukturiert die Arbeits- und Lernprozesse eigenständig.
 Zuverlässigkeit und Sorgfalt: ... hält sich an vereinbarte Absprachen.
</code></pre><h3 id="zeilenumbruche" tabindex="-1">Zeilenumbrüche <a class="header-anchor" href="#zeilenumbruche" aria-label="Permalink to &quot;Zeilenumbrüche&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-ankreuzkompetenzen-zeilenumbruch.png"><img src="`+h+'" alt="Durch Einsatz der Raute # lassen sich in Kompetenz und auch bei der Benennung der Kompetenzstufen Zeilenumbrüche erzeugen." loading="lazy"></a></p><p><em>Durch Einsatz der Raute <strong>#</strong> lassen sich in Kompetenz und auch bei der Benennung der Kompetenzstufen Zeilenumbrüche erzeugen.</em></p><p>Für lange mehrzeilig ausfallende Kompetenzen wird ein automatischer Zeilenumbruch erzeugt. Dieser sieht aber mitunter nicht gut aus, außerdem fehlt ein Versatz vor der neuen Zeile.</p><p>Mit dem Doppelkreuz (der Raute) <strong>#</strong> lässt sich ein Zeilenumbruch erzwingen, der auch einen Versatz in der Folgezeile erzeugt.</p><p>Dieser erzwungene Zeilenumbruch funktioniert ebenfalls bei der Beschreibung der Kompetenz<strong>stufen</strong> - siehe unten - um diese zweizeilig ausfallen lassen.</p>',15),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,"Werden keine Stufen benannt, werden nur vier Stufen zum Ankreuzen angezeigt. Benennen Sie alle fünf Stufen, stehen auch alle fünf zum Anklicken zur Auswahl.")],-1),n('<p><a href="/bilder/unterricht-kataloge/kataloge-ankreuzkompetenzen-zeilenumbruch-beispiel.png"><img src="'+p+'" alt="Die Zeilenumbrüche werden im Reportdruck dort erzeugt, wo die Rauten # in den Kompetenzbeschreibungen und den Kompetenzstufen gesetzt wurden. Beachten Sie, dass nun im Unterschied zum Beispiel zu den &quot;Unterkategorien&quot; (oben) fünf Kompetenzstufen zur Verfügung stehen." loading="lazy"></a></p><p><em>Die Zeilenumbrüche werden im Reportdruck dort erzeugt, wo die Rauten <strong>#</strong> in den Kompetenzbeschreibungen und den Kompetenzstufen gesetzt wurden. Beachten Sie, dass nun im Unterschied zum Beispiel zu den &quot;Unterkategorien&quot; (oben) fünf Kompetenzstufen zur Verfügung stehen.</em></p><h2 id="stufen-definieren" tabindex="-1">Stufen definieren <a class="header-anchor" href="#stufen-definieren" aria-label="Permalink to &quot;Stufen definieren&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-kompetenzen-benennen.png"><img src="'+t+'" alt="Benennen Sie die Kompetenzstufen. Wird die fünfte weggelassen, werden auch nur vier Kästchen zum Ankreuzen ausgedruckt. Beachten Sie bitte ebenfalls die #, mit denen ein wohldefinierter Zeilenumbruch erzeugt wird. Ebenfalls zu sehen ist hier die Frei definierbare Zeugnisrubrik." loading="lazy"></a></p><p><em>Benennen Sie die Kompetenz<strong>stufen</strong>. Wird die fünfte weggelassen, werden auch nur vier Kästchen zum Ankreuzen ausgedruckt. Beachten Sie bitte ebenfalls die <strong>#</strong>, mit denen ein wohldefinierter Zeilenumbruch erzeugt wird. Ebenfalls zu sehen ist hier die Frei definierbare Zeugnisrubrik.</em></p><p>Unterhalb der Kompetenzbeschreibungen werden die Stufen der Kompetenzen schriftlich festgelegt. Auch hier können Zeilenumbrüche mit einem Doppelkreuz <strong>#</strong> definiert werden.</p><p>Lassen Sie die fünfte Kompetenzstufe weg, werden auch nur vier Kästchen zum Ankreuzen auf dem Zeugnis erzeugt.</p><h2 id="frei-definierbare-zeugnisrubrik" tabindex="-1">Frei definierbare Zeugnisrubrik <a class="header-anchor" href="#frei-definierbare-zeugnisrubrik" aria-label="Permalink to &quot;Frei definierbare Zeugnisrubrik&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges.png"><img src="'+a+'" alt="Hier wird das Fach Sonstiges zusammen mit der frei definierbaren Rubrik genutzt, um einen für diese Schule sehr wichtigen Umgang mit Medientechnik abzubilden." loading="lazy"></a></p><p><em>Hier wird das Fach Sonstiges zusammen mit der frei definierbaren Rubrik genutzt, um einen für diese Schule sehr wichtigen Umgang mit Medientechnik abzubilden.</em></p><p>Über dieses Feld kann eine Rubrik frei benannt werden, die auf dem Zeugnis auftauchen soll.</p><p>Haben Sie zum Beispiel einen Schulbauernhof, Medientechnik oder ein an der Schule tief verankertes aktives Musik- und Theaterleben, kann diese Rubrik als Pseudo-Fach genutzt werden.</p><p>Wurde hier etwas eingetragen, können über das <strong>Fach</strong> <em>Sonstiges</em> wie üblich ankreuzbare Kompetenzen erzeugt werden.</p><h2 id="begrundung-der-ubergangsempfehlung-mit-ankreuzkompetenzen" tabindex="-1">Begründung der Übergangsempfehlung mit Ankreuzkompetenzen <a class="header-anchor" href="#begrundung-der-ubergangsempfehlung-mit-ankreuzkompetenzen" aria-label="Permalink to &quot;Begründung der Übergangsempfehlung mit Ankreuzkompetenzen&quot;">​</a></h2><p><a href="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges-uebergangsempfehlung.png"><img src="'+m+'" alt="Hier wird das Fach Sonstiges genutzt, um die Begründung der Übergangsempfehlung als Ankreuzteil abzubilden." loading="lazy"></a></p><p><em>Hier wird das Fach Sonstiges genutzt, um die Begründung der Übergangsempfehlung als Ankreuzteil abzubilden.</em></p><p>Das frei definierbare Feld bietet eine einfache Möglichkeit, die Begründung der Übergangsempfehlung für den Schulformwechsel im 4. Jahrgang durch Ankreuzen übersichtlich und einfach umzusetzen. Sowohl das aktuelle Hybridzeugnis als auch der Einzelreport für die Übergangsempfehlung wurden entsprechend angepasst, sodass die hier definierten Übergangskompetenzen für den Jahrgang 4 an der richtigen Stelle in der Anlage bzw. im Zeugnis abgebildet werden.</p>',17),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,'Um die Begründung der Übergangsempfehlung mit Ankreuzkompetenzen zu realisieren, muss in der Klassen-/Versetzungstabelle für die 4. Klassen der Haken bei "In dieser Klasse werden Ankreuzzeugnisse verwendet" gesetzt sein.')],-1),n('<p>Sie können Übergangskompetenzen unter eigenen Überschriften gliedern. Schreiben Sie dazu die Überschrift und einen Doppelpunkt vor die Kompetenzbeschreibung, etwa <strong>Mitarbeit:</strong> oder <strong>Arbeitstempo:</strong>. Hinter dem Doppelpunkt folgt die zugehörige Beschreibung.</p><p><a href="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges-uebergangsempfehlung-unterkategorie.png"><img src="'+c+'" alt="Hier werden die Übergangsfloskeln in weitere Unterkategorien eingeteilt. In dem Beispiel erscheinen später im Zeugnisreport drei Kompetenzen für den Bereich Mitarbeit und eine Kompetenz für den Bereich Arbeitstempo. Es können beliebig weitere Unterkategorien hinzugefügt werden." loading="lazy"></a></p><p><em>Hier werden die Übergangsfloskeln in weitere Unterkategorien eingeteilt. In dem Beispiel erscheinen später im Zeugnisreport drei Kompetenzen für den Bereich <strong>Mitarbeit</strong> und eine Kompetenz für den Bereich <strong>Arbeitstempo</strong>. Es können beliebig weitere Unterkategorien hinzugefügt werden.</em></p><p><a href="/bilder/unterricht-kataloge/tutorials-gs-ankreuzzeugnisse-frei-definierbares-sonstiges-uebergangsempfehlung-ausdruck.png"><img src="'+z+'" alt="Für das obige Beispiel erscheint so die Angabe im Zeugnis." loading="lazy"></a></p><p><em>Für das obige Beispiel erscheint so die Angabe im Zeugnis.</em></p><h2 id="nutzung-von-ankreuzkompetenzen" tabindex="-1">Nutzung von Ankreuzkompetenzen <a class="header-anchor" href="#nutzung-von-ankreuzkompetenzen" aria-label="Permalink to &quot;Nutzung von Ankreuzkompetenzen&quot;">​</a></h2>',6),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),r("Hinweis")]),e("p",null,"Nutzen Sie hierzu die Anleitung für Ankreuzzeugnisse in der Grundschule.")],-1),n('<p><strong>Das Vorgehen in Kürze:</strong></p><ol><li>Laden Sie einen Ankreuzkompetenzen nutzenden Zeugnisreport von der <a href="https://www.svws.nrw.de" target="_blank" rel="noreferrer">Webseite für Schulverwaltungssoftware des MSB</a> herunter und</li><li>installieren Sie ihn im SchILD-Arbeitsverzeichnis im Ordner <em>Schild-Reports</em>.</li><li>Schalten Sie die Klassen, in denen Ankreuzkompetenzen verwendet werden sollen, über <em>Kataloge ➜</em> <strong>Klassen-/Versetzungstabelle</strong> frei, in dem der entsprechende Haken gesetzt wird.</li><li>Unter dem Karteireiter <em>Schüler ➜ Akt. Halbjahr</em> gibt es nun einen neuen Reiter für <em>Kompetenzen für Ankreuzzeugnisse</em>.</li><li>Holen Sie per Klick in diesem Reiter oder über <em>Gruppenprozesse ➜ Noten/Zeugnisvorbereitung ➜</em> <strong>Ankreuzkompetenzen eintragen</strong> die Kompetenzen zu den Schülern.</li><li>Haken Sie nun bei den Schülern die jeweiligen Kompetenzen an.</li><li>Führen Sie die übliche Zeugnisvorbereitung und den Zeugnisdruck mit den Reports für Ankreuzzeugnisse durch.</li></ol><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Ankreuzkompetenzen_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5883.</p>',4)])])}const Z=s(k,[["render",b]]);export{B as __pageData,Z as default};
